#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    if (n <= 0) {
        printf("0\n");
        return 0;
    }

    static int last[100001];
    for (int i = 0; i <= 100000; i++) {
        last[i] = -1;
    }

    int left = 0;
    int best = 0;

    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);

        if (last[x] >= left) {
            left = last[x] + 1;
        }

        int len = i - left + 1;
        if (len > best) {
            best = len;
        }

        last[x] = i;
    }

    printf("%d\n", best);
    return 0;
}
```

